+fn lock_replaced_view(
+    target_dir: &Path,
+    managed: &Path,
+    workspace_root: &Path,
+) -> Result<Vec<fslock::LockFile>> {
+    let Ok(existing) = std::fs::read_link(target_dir) else {
+        return Ok(Vec::new());
+    };
