+        return Ok(Vec::new());
+    }
+    let mut pending = vec![(existing, 0)];
+    let mut locks = Vec::new();
+    while let Some((directory, depth)) = pending.pop() {
+        for entry in std::fs::read_dir(&directory)? {
+            let entry = entry?;
+            let kind = entry.file_type()?;
